WITH enriched AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, CORR(price, cost) OVER (PARTITION BY supplier_id) corr_price_cost, NTILE(4) OVER (PARTITION BY category ORDER BY price, id) price_bucket, SUM(cost) OVER (PARTITION BY supplier_id, category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_cost FROM products) SELECT CASE WHEN price >= 1140 THEN 'HIGH' ELSE 'LOW' END AS price_tier, CASE WHEN cumulative_cost >= 3850 THEN 'PREMIUM' ELSE 'STANDARD' END AS cumulative_cost_tier, COUNT(*) AS event_count, ROUND(AVG(corr_price_cost), 2) AS avg_corr_price_cost, COUNT_IF(brand = 'Stark') AS stark_events FROM enriched GROUP BY CASE WHEN price >= 1140 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN cumulative_cost >= 3850 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY cumulative_cost_tier DESC;
